(function(){'use strict';const config={rootMargin:'50px 0px',threshold:0.01};const loadedImages=new Set();const imageObserver=new IntersectionObserver((entries,observer)=>{entries.forEach(entry=>{if(entry.isIntersecting){const img=entry.target;loadImage(img);observer.unobserve(img);}});},config);function loadImage(img){const src=img.dataset.src || img.getAttribute('data-src');if(!src || loadedImages.has(src))return;const srcset=img.dataset.srcset || img.getAttribute('data-srcset');const tempImg=new Image();tempImg.onload=()=>{img.src=src;if(srcset)img.srcset=srcset;img.classList.add('loaded');loadedImages.add(src);img.dispatchEvent(new CustomEvent('imageLoaded',{detail:{src:src,loadTime:performance.now()}}));};tempImg.onerror=()=>{console.error('Failed to load image:',src);img.classList.add('error');img.src='/images/meme-placeholder.svg';};tempImg.src=src;}function initLazyLoad(){const lazyImages=document.querySelectorAll('img[data-src],img[loading="lazy"]');let observedCount=0;lazyImages.forEach(img=>{if(img.getAttribute('fetchpriority')==='high' || img.getAttribute('loading')==='eager'){return;}img.classList.add('lazy-loading');imageObserver.observe(img);observedCount++;});if(observedCount > 0){console.log(`✅ Enhanced lazy loading initialized for ${observedCount}images`);}}function prefetchNextImage(url){if(!url || loadedImages.has(url))return;const link=document.createElement('link');link.rel='prefetch';link.as='image';link.href=url;document.head.appendChild(link);loadedImages.add(url);}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initLazyLoad);}else{initLazyLoad();}const contentObserver=new MutationObserver((mutations)=>{let hasNewImages=false;mutations.forEach(mutation=>{mutation.addedNodes.forEach(node=>{if(node.nodeType===1){if(node.tagName==='IMG' || node.querySelector('img')){hasNewImages=true;}}});});if(hasNewImages){initLazyLoad();}});contentObserver.observe(document.body,{childList:true,subtree:true});window.LazyLoad={init:initLazyLoad,prefetch:prefetchNextImage,isLoaded:(src)=> loadedImages.has(src)};})();